import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  bg: "#0A0E0C",
  primary: "#f86606",
  light: "#ff7f10",
  dark: "#c74907",
  cream: "rgba(255,250,240,0.92)",
  muted: "rgba(255,250,240,0.5)",
  faint: "rgba(255,250,240,0.25)",
};

const TRANSITION = 15;

const SNAPPY = { mass: 0.5, damping: 14, stiffness: 220 };
const ELASTIC = { mass: 0.8, damping: 10, stiffness: 180 };
const LIQUID = { mass: 1.0, damping: 22, stiffness: 120 };
const GENTLE = { mass: 1.0, damping: 30, stiffness: 80 };

const FONT = "'Inter', sans-serif";

const Background: React.FC = () => null;

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ============================================================
// SCENE 1 — "Clicks are dropping. Rankings haven't changed.
//          Impressions are up." (0:00 - 0:09)
// ============================================================
const SceneMetrics: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const clicksIn = spring({ frame, fps, delay: 8, config: GENTLE });
  const clicksLineProgress = interpolate(frame, [20, 110], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const rankIn = spring({ frame, fps, delay: 65, config: GENTLE });
  const rankLineProgress = interpolate(frame, [75, 150], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const impIn = spring({ frame, fps, delay: 120, config: GENTLE });
  const impLineProgress = interpolate(frame, [130, 200], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const buildLine = (points: { x: number; y: number }[], progress: number) => {
    const total = points.length;
    const visible = Math.floor(total * progress);
    const partial = (total * progress) % 1;
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i <= visible && i < total; i++) {
      d += ` L ${points[i].x} ${points[i].y}`;
    }
    if (visible < total - 1 && partial > 0) {
      const a = points[visible];
      const b = points[visible + 1];
      const x = a.x + (b.x - a.x) * partial;
      const y = a.y + (b.y - a.y) * partial;
      d += ` L ${x} ${y}`;
    }
    return d;
  };

  const clicksPts = [
    { x: 0, y: 60 },
    { x: 100, y: 70 },
    { x: 200, y: 90 },
    { x: 300, y: 120 },
    { x: 400, y: 160 },
    { x: 500, y: 200 },
    { x: 600, y: 240 },
  ];
  const rankPts = [
    { x: 0, y: 140 },
    { x: 150, y: 138 },
    { x: 300, y: 142 },
    { x: 450, y: 139 },
    { x: 600, y: 141 },
  ];
  const impPts = [
    { x: 0, y: 250 },
    { x: 100, y: 230 },
    { x: 200, y: 200 },
    { x: 300, y: 160 },
    { x: 400, y: 120 },
    { x: 500, y: 80 },
    { x: 600, y: 40 },
  ];

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONT,
      }}
    >
      <div
        style={{
          width: "100%",
          height: "100%",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: "8%",
            top: "14%",
            width: "84%",
            display: "flex",
            flexDirection: "column",
            gap: 50,
          }}
        >
          {/* CLICKS DROPPING */}
          <div
            style={{
              opacity: clicksIn,
              transform: `translateY(${interpolate(clicksIn, [0, 1], [40, 0])}px)`,
              backgroundColor: "rgba(255,250,240,0.04)",
              border: "0.5px solid rgba(255,250,240,0.08)",
              borderRadius: 32,
              padding: "44px 56px",
              display: "flex",
              alignItems: "center",
              gap: 40,
              fontFamily: FONT,
            }}
          >
            <div style={{ flex: 1 }}>
              <div
                style={{
                  fontFamily: FONT,
                  fontSize: 26,
                  fontWeight: 500,
                  color: COLORS.muted,
                  letterSpacing: "0.18em",
                  textTransform: "uppercase",
                  marginBottom: 16,
                }}
              >
                Clicks
              </div>
              <div
                style={{
                  fontFamily: FONT,
                  fontSize: 110,
                  fontWeight: 300,
                  color: COLORS.cream,
                  lineHeight: 1,
                  letterSpacing: "-0.03em",
                }}
              >
                Dropping
              </div>
            </div>
            <svg width={620} height={300} viewBox="0 0 620 300">
              <path
                d={buildLine(clicksPts, clicksLineProgress)}
                stroke={COLORS.dark}
                strokeWidth={4}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              {clicksLineProgress > 0.95 && (
                <circle
                  cx={600}
                  cy={240}
                  r={10}
                  fill={COLORS.dark}
                  opacity={interpolate(frame, [108, 120], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  })}
                />
              )}
            </svg>
          </div>

          {/* RANKINGS FLAT */}
          <div
            style={{
              opacity: rankIn,
              transform: `translateY(${interpolate(rankIn, [0, 1], [40, 0])}px)`,
              backgroundColor: "rgba(255,250,240,0.04)",
              border: "0.5px solid rgba(255,250,240,0.08)",
              borderRadius: 32,
              padding: "44px 56px",
              display: "flex",
              alignItems: "center",
              gap: 40,
              fontFamily: FONT,
            }}
          >
            <div style={{ flex: 1 }}>
              <div
                style={{
                  fontFamily: FONT,
                  fontSize: 26,
                  fontWeight: 500,
                  color: COLORS.muted,
                  letterSpacing: "0.18em",
                  textTransform: "uppercase",
                  marginBottom: 16,
                }}
              >
                Rankings
              </div>
              <div
                style={{
                  fontFamily: FONT,
                  fontSize: 110,
                  fontWeight: 300,
                  color: COLORS.cream,
                  lineHeight: 1,
                  letterSpacing: "-0.03em",
                }}
              >
                Unchanged
              </div>
            </div>
            <svg width={620} height={300} viewBox="0 0 620 300">
              <path
                d={buildLine(rankPts, rankLineProgress)}
                stroke={COLORS.muted}
                strokeWidth={4}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray="8 8"
              />
            </svg>
          </div>

          {/* IMPRESSIONS UP */}
          <div
            style={{
              opacity: impIn,
              transform: `translateY(${interpolate(impIn, [0, 1], [40, 0])}px)`,
              backgroundColor: "rgba(255,250,240,0.04)",
              border: "0.5px solid rgba(255,250,240,0.08)",
              borderRadius: 32,
              padding: "44px 56px",
              display: "flex",
              alignItems: "center",
              gap: 40,
              fontFamily: FONT,
            }}
          >
            <div style={{ flex: 1 }}>
              <div
                style={{
                  fontFamily: FONT,
                  fontSize: 26,
                  fontWeight: 500,
                  color: COLORS.muted,
                  letterSpacing: "0.18em",
                  textTransform: "uppercase",
                  marginBottom: 16,
                }}
              >
                Impressions
              </div>
              <div
                style={{
                  fontFamily: FONT,
                  fontSize: 110,
                  fontWeight: 300,
                  color: COLORS.light,
                  lineHeight: 1,
                  letterSpacing: "-0.03em",
                }}
              >
                Rising
              </div>
            </div>
            <svg width={620} height={300} viewBox="0 0 620 300">
              <path
                d={buildLine(impPts, impLineProgress)}
                stroke={COLORS.light}
                strokeWidth={4}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              {impLineProgress > 0.95 && (
                <circle
                  cx={600}
                  cy={40}
                  r={10}
                  fill={COLORS.light}
                  opacity={interpolate(frame, [198, 210], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  })}
                />
              )}
            </svg>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

